import { useEffect, useRef, useState } from "react";
import HeroCard from "./HeroCard";
import { lerp, clamp, ease } from "./helpers";
import '../index.css';

const CARDS = [
  { id: 1,  label: "Vehicle RC",      angle: 180,   rotate: -14, z: 26 },
  { id: 2,  label: "DL Verification", angle: 147.3, rotate: 9,   z: 27 },
  { id: 3,  label: "KYC Check",       angle: 114.5, rotate: -6,  z: 28 },
  { id: 4,  label: "Aadhaar",         angle: 81.8,  rotate: 5,   z: 29 },
  { id: 5,  label: "Face Match",      angle: 49.1,  rotate: -9,  z: 29 },
  { id: 6,  label: "PAN Card",        angle: 16.4,  rotate: 12,  z: 28 },
  { id: 7,  label: "Fraud Alert",     angle: 343.6, rotate: -5,  z: 27 },
  { id: 8,  label: "Bank Verify",     angle: 310.9, rotate: 11,  z: 28 },
  { id: 9,  label: "Credit Score",    angle: 278.2, rotate: -5,  z: 29 },
  { id: 10, label: "Background Chk",  angle: 245.5, rotate: -10, z: 28 },
  { id: 11, label: "Employment",      angle: 212.7, rotate: 9,   z: 27 },
];

export default function HeroSection() {
  const [progress, setProgress] = useState(0);
  const [vw, setVw]             = useState(0);
  const sectionRef              = useRef(null);

  useEffect(() => {
    const onScroll = () => {
      const el = sectionRef.current;
      if (!el) return;
      const p = clamp(
        -el.getBoundingClientRect().top / (el.offsetHeight * 0.62),
        0, 1
      );
      setProgress(p);
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  useEffect(() => {
    const update = () => setVw(window.innerWidth);
    update();
    window.addEventListener("resize", update, { passive: true });
    return () => window.removeEventListener("resize", update);
  }, []);

  const headingScale = lerp(0.44, 1, ease(clamp(progress / 0.75, 0, 1)));

  return (
    <div ref={sectionRef} style={{ height: "300vh", position: "relative" }}>
      <div
        id="home-banner"
        style={{
          position: "sticky",
          top: 30,
          height: "100vh",
          overflow: "hidden",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        {/* Grid background */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            backgroundImage:
              "linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px)," +
              "linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px)",
            backgroundSize: "clamp(32px, 4vw, 48px) clamp(32px, 4vw, 48px)",
          }}
        />

        {/* ── Hero text block — z:15 so cards (z:25+) always paint on top ── */}
        <div
          style={{
            position: "absolute",
            zIndex: 15,
            textAlign: "center",
            transform: `scale(${headingScale})`,
            willChange: "transform",
            width: "100%",
            padding: "0 clamp(12px, 2vw, 60px)",
          }}
        >
          {/*
           * Font math:
           *   "Click to the Doorstep" is the longer line (~22 chars).
           *   At 5.8vw on a 1440px viewport → 5.8 * 14.4 = ~84px per line.
           *   Both lines sit well within 1440px width.  Cap at 96px for 1920+.
           *   whiteSpace is left at default ("normal") so the <br /> controls
           *   the break — no nowrap interference.
           */}
          <h1
            style={{
              fontFamily: "'Inter', sans-serif",
              fontSize: "clamp(28px, 5.8vw, 96px)",
              fontWeight: 900,
              color: "white",
              margin: 0,
              lineHeight: 1.08,
              whiteSpace: "normal",        /* allow <br /> to split lines   */
              overflowWrap: "normal",      /* don't soft-wrap mid-word       */
              wordBreak: "keep-all",       /* keep each line as one unit     */
            }}
          >
            Deception from
            <br />
            Click to the Doorstep
          </h1>

          {/*
           * Subtitle at exactly 30px as requested.
           * No zIndex here — inherits parent's z:15 stacking context,
           * so cards wrapper (z:25) and individual cards (z:26-29) overlap it.
           */}
          <p
            style={{
              fontSize: "30px",
              fontWeight: 500,
              color: "white",
              margin: "20px 0 0 0",
              lineHeight: 1.3,
              opacity: 0.88,
            }}
          >
            A closer look at the risks in India's gig workforce.
          </p>
        </div>

        {/* ── Cards layer — z:25 wrapper guarantees all cards sit above text ── */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            pointerEvents: "none",
            overflow: "hidden",
            zIndex: 25,
          }}
        >
          {CARDS.map(c => (
            <HeroCard key={c.id} card={c} progress={progress} vw={vw} />
          ))}
        </div>
      </div>
    </div>
  );
}
